    /// <summary>
    /// update METTariffItemCodeBase reference
    /// </summary>
    /// <returns>true if valid</returns>
    public boolean validateWrite()
    {
        boolean ret;
    
        ret = super();

        if(ret)
        {
            METStatCode statCode;
            METNAT3040  nat3040;
            if(this.CustomsExcise == METCustomExcise::C)
            {
                nat3040  = METNAT3040::NAT30;
                statCode = this.StatCode;
            }
            else
            {
                nat3040   = METNAT3040::NAT40;
                statCode  = "@MET:DefaultStatCodeText";
            }

            METTariffItemCodeBase METTariffItemCodeBase = METTariffItemCodeBase::findbyTariffStatCode(this.TariffItem, statCode);

            if(!METTariffItemCodeBase)
            {
                METTariffItemCodeBase.TariffItem    = this.TariffItem;
                METTariffItemCodeBase.StatCode      = statCode;
                METTariffItemCodeBase.NAT3040       = nat3040;
                METTariffItemCodeBase.Description   = this.Description;
                METTariffItemCodeBase.CustomsExcise = this.CustomsExcise;

                ttsbegin;
                METTariffItemCodeBase.insert();
                ttscommit;
            }

            this.METTariffItemCodeBaseRecId = METTariffItemCodeBase.RecId;
            this.StatCode = statCode;

            if(!this.ValidTo)
            {
                this.ValidTo = dateMax();
            }
        }
        this.updateActiveTariffItemCodeValidToDate(); /// MPJ_5013_ExciseRegister by chaminda on 23 Feb 2022
    
        return ret;
    }

    /// <summary>
    /// MPJ_5013_ExciseRegister by chaminda on 23 Feb 2022
    /// </summary>
    private void updateActiveTariffItemCodeValidToDate()
    {
        METTariffItemCode   metTariffItemCode,metTariffItemCodeUpdate;
        ValidFromDate   validFromDate   = this.ValidFrom;
        ValidToDate     validToDate     = this.ValidTo;
        utcdatetime     currentDate     = DateTimeUtil::utcNow();
        
        select firstonly validtimestate(currentDate) metTariffItemCode
            where metTariffItemCode.METTariffItemCodeBase == this.METTariffItemCodeBaseRecId;
        if(!metTariffItemCode)
        {
            select firstonly validtimestate(validFromDate,validToDate) metTariffItemCode
                where metTariffItemCode.METTariffItemCodeBase == this.METTariffItemCodeBaseRecId;
        }
        if(metTariffItemCode)
        {
            ttsbegin;
            metTariffItemCode.selectForUpdate(true);
            
            if(metTariffItemCode.ValidTo <= this.ValidTo) 
            {                                
                if(metTariffItemCode.ValidFrom < this.ValidFrom)
                {
                    metTariffItemCode.validTimeStateUpdateMode(ValidTimeStateUpdate::Correction);
                    metTariffItemCode.ValidTo = this.ValidFrom-1;
                    metTariffItemCode.doUpdate();
                }
               
            }
                        
            ttscommit;
        }
        

        
    }

    /// <summary>
    /// MPJ_5013_ExciseRegister by chaminda on 23 Feb 2022
    /// </summary>
    public static void postGetStagingData(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
    {
        METTariffItemCodeStaging    metTariffItemCodeStaging;
        ttsbegin;
            
        while select forupdate metTariffItemCodeStaging
            where metTariffItemCodeStaging .DefinitionGroup     == _dmfDefinitionGroupExecution.DefinitionGroup &&
                  metTariffItemCodeStaging .ExecutionId         == _dmfDefinitionGroupExecution.ExecutionId  &&
                  metTariffItemCodeStaging .TransferStatus      == DMFTransferStatus::NotStarted             &&
                  !metTariffItemCodeStaging.ValidTo


        {
            metTariffItemCodeStaging.validTimeStateUpdateMode(ValidTimeStateUpdate::Correction);
            metTariffItemCodeStaging.ValidTo = dateMax();
            metTariffItemCodeStaging.doUpdate();
            
        }
        ttscommit;
    }
